    /// @brief GET swtName.0. @return The value. @throws snmpwrap::Error, snmpwrap::TransportError, snmpwrap::ResponseError
    std::string swtName();
    /// @brief SET swtName.0. @param[in] value New value. @throws snmpwrap::SetError (MIB check), snmpwrap::TransportError, snmpwrap::ResponseError
    void setSwtName(const std::string& value);

