    std::uint32_t swtGauge();

    /// @brief GET swtLimit.0. @return The value. @throws snmpwrap::Error, snmpwrap::TransportError, snmpwrap::ResponseError
    std::int32_t swtLimit();
    /// @brief SET swtLimit.0. @param[in] value New value. @throws snmpwrap::SetError (MIB check), snmpwrap::TransportError, snmpwrap::ResponseError
    void setSwtLimit(std::int32_t value);

    /// @brief GET swtUptime.0. @return The value. @throws snmpwrap::Error, snmpwrap::TransportError, snmpwrap::ResponseError
