    /// @brief GET one cell of swtEntryStatus. @param[in] index Row index. @return The value.
    SwtEntryStatus swtEntryStatus(const SwtEntryIndex& index);
    /// @brief SET one cell of swtEntryStatus. @param[in] index Row index. @param[in] value New value.
